    //MSSCUSTODY - 3658 Checker Task Verification
    bulkCheckerTaskVerification: function(bulkID, userID) {

        /*The method checks for all the ineligible trades which holds high Nominal Settlement /Settlement amount in USD 
        with respect to the current assigned Checker's allowed band limit USD and the decision matrix is populated
        Based on the decision matrix[false, true....] the trdApprEligibility will be set to false or true which is utilized in the 
        Business rule - Validate Band Limit for Checker - Bulk
        */

        var trades = []; ////fetching all the checker task with confirm or settle trade
        var highValTrades = []; //Ineligible Trades
        var decMatrix = []; //holds true or false for approver eligibility
        var trdApprEligibility = ''; //true or false based on the decMatrix
        var embeddedLink = ''; //Clickable link for the trade ID

        //fetching all the checker task with confirm or settle trade
        var bul = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        bul.addEncodedQuery('active=true^trade_task_type=Checker^sub_trade_task_type=Checker^bulk_id.sys_idSTARTSWITH' + bulkID); //modified as part of defect MSSCUSTODY-4172
        bul.query();
        while (bul.next()) {
            trades.push(bul.trade_id + '');
        }
        //fetching all the checker task with confirm or settle trade

        if (trades.length > 0) { //added as part if  defect MSSCUSTODY-4172 to validate if there are any tasks as per the query

            //fetching the trade nominal and settlement amount in USD
            for (var i = 0; i < trades.length; i++) {
                var grTrade = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
                grTrade.get(trades[i]);
                var nomAmt = grTrade.nominal_settlement_amount_in_usd; // nominal_settlement_amount_in_usd
                var setAmt = grTrade.settlement_amount_in_usd; //settlement_amount_in_usd
                var transType = grTrade.getValue('transaction_type'); //DVP or RVP*/


                //if (nomAmt != 0 || nomAmt != '' || setAmt != 0 || setAmt != '') { //if nominal or settlement amount is valid // disabled this check to enable the non- band users to see which trades are not eligible

                //Fetching the Group type in sys_user_group_type table based on the Trade owning business
                var owningBusiness = grTrade.owning_business; //trade owning business
                var trdType = new GlideRecord('sys_user_group_type');
                trdType.get(owningBusiness);
                var typeID = trdType.sys_id;
                //Fetching the Group type in sys_user_group_type table based on the Trade owning business

                //Fetching the user associated groups to check if user belongs to the trade owning business group
                var grUser = new GlideRecord('sys_user');
                grUser.get(userID);
                var userMarket = grUser.u_associated_business_markets; //associated markets of user
                var usrBand = grUser.u_user_band; //user band
                //Fetching the user associated groups to check if user belongs to the trade owning business group



                if ((userMarket.indexOf(owningBusiness) > -1) && (usrBand != '')) { //added to restrict users not having ay band
                    var grGroup = new GlideRecord("sys_user_group");
                    grGroup.addEncodedQuery('typeLIKE' + typeID + '^u_group_location=Onshore^u_associated_group_band=' + usrBand); //Considering only access groups
                    grGroup.orderByDesc('group.u_local_limit');
                    grGroup.query();
                    if (grGroup.next()) {

                        if (transType == 'DVP' || transType == 'RVP') {
                            //if ((grTrade.settlement_amount_in_usd > grGroup.u_usd_limit)) { // Commented as part of MSSUSTODY 6459
                            if ((grTrade.settlement_amount_in_usd > grGroup.u_local_limit.getReferenceValue())) {

                                embeddedLink = "<a href='/nav_to.do?uri=x_hsb11_mss_c_proc_mss_custody_trade.do?sys_id=" + grTrade.sys_id + " ' target='_blank'><strong>" + grTrade.trade_id + "</strong></a>";
                                highValTrades.push(embeddedLink + " |" + '');
                                decMatrix.push(false + ''); //Higher limit than USD limit for DVP and RVP
                            }
                        } else if (transType == 'RFP' || transType == 'DFP' || transType != '') { //including all transaction type t ocheck limit as per story MSSCUSTODY-4238
                            //if ((grTrade.nominal_settlement_amount_in_usd > grGroup.u_usd_limit)) { // Commented as part of MSSCUSTODy-6459
                            if ((grTrade.nominal_settlement_amount_in_usd > grGroup.u_local_limit.getReferenceValue())) {

                                embeddedLink = "<a href='/nav_to.do?uri=x_hsb11_mss_c_proc_mss_custody_trade.do?sys_id=" + grTrade.sys_id + " ' target='_blank'><strong>" + grTrade.trade_id + "</strong></a>";
                                highValTrades.push(embeddedLink + " |" + '');
                                decMatrix.push(false + ''); //Higher limit than USD limit for FOP
                            }
                        }

                    } else {
                        decMatrix.push(false + ''); //User Does not belong to any groups allowed for trade approval
                    }
                } else { //added to show the ineligible trades to users not having any band
                    embeddedLink = "<a href='/nav_to.do?uri=x_hsb11_mss_c_proc_mss_custody_trade.do?sys_id=" + grTrade.sys_id + " ' target='_blank'><strong>" + grTrade.trade_id + "</strong></a>";
                    highValTrades.push(embeddedLink + " |" + '');
                    decMatrix.push(false + ''); //User Does not belong to Trade market
                }
                //}
            } //fetching the trade nominal and settlement amount in USD

            //Populate the decision matrix with 'false' if any of the trades are noteligible
            if (decMatrix.indexOf('false') > -1) {
                trdApprEligibility = 'false';
            }
            //Populate the decision matrix with 'false' if any of the trades are noteligible

            var tradeApprovalCheck = {
                "tradeEligibility": trdApprEligibility,
                "highValTrades": highValTrades.toString()
            };

            return JSON.stringify(tradeApprovalCheck);

        }
    },
