        //gs.info("RSJ RO:" + bulkID);
        //var taskID = this.getParameter('sysparm_taskID'); //get the passed array of sys_ids
        //gs.info(taskID + 'Sanofi');
        var cusTsk = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        cusTsk.addEncodedQuery('sys_idIN' + taskID); //query to find all records with the passed sys_ids
        cusTsk.query();
        //  var removedTaskIds = [];
        while (cusTsk.next()) {
            //var blk_no = cusTsk.bulk_id;

            // cusTsk.work_notes = this.getParameter('sysparm_comments');
            //bulkID123 = cusTsk.bulk_id;
            //  gs.info(bulkID + 'sanofi1');
            var caseType = cusTsk.trade_id.case_type;
            //  gs.info(caseType + 'Lonza');

            if (caseType == 'manual') {
                cusTsk.setValue('state', '7');
                cusTsk.setValue('active', 'false');
                //MSSCUSTODY-3993.
                cusTsk.lock = false;
                cusTsk.setValue('assigned_to', '');
                cusTsk.setValue('assignment_group', '');

                var cusCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                if (cusCase.get(cusTsk.trade_case_id)) {
                    cusCase.setValue('state', '3');
                    cusCase.setValue('active', 'false');
                    cusCase.update();



                    // var grFlow = new GlideRecord('sys_flow_context'); // Cancelling the flow context when the case is closing as part of FOL Event
                    // grFlow.addQuery('source_record', cusTsk.trade_case_id);
                    // grFlow.query();
                    // while (grFlow.next()) {
                    //     sn_fd.FlowAPI.cancel(grFlow.sys_id, 'Cancelling active flows for active false custody cases');
                    //    // gs.info("this cancels the flow");
                    // }

                }

            }
            if (caseType == 'automated') {
                // gs.info('Sanofi2');
                cusTsk.bulk_id = "NULL";
                //cusTsk.setValue('bulk_id', '');
                //cusTsk.setValue('outcome', '');//fix for MSSCUSTODY-3959
                cusTsk.setValue('state', '1');
                //cusTsk.setValue('assignment_group', '');
                //cusTsk.setValue('assigned_to', '');
                // cusTsk.assignment_group = "NULL";
                // cusTsk.assigned_to = "";
                //cusTsk.update();
                //MSSCUSTODY-3993, MSSCUSTODY-4295
                cusTsk.lock = false;
                cusTsk.setValue('assigned_to', '');
                cusTsk.setValue('assignment_group', '');

                var cusCase1 = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                if (cusCase1.get(cusTsk.trade_case_id)) {
                    cusCase1.bulk_id = "NULL";
                    cusCase1.update();
                }
            }
            //MSSCUSTODY-4282
            new x_hsb11_mss_c_proc.MSSCustodyBulkUtils_workspace().decrementTradeCount(bulkID);

            cusTsk.update();
            //  removedTaskIds.push(cusTsk.getUniqueValue()); //added as part of MSSCUSTODY-6269
        }
        //MSSCUSTODY-6269
        /* if (removedTaskIds.length > 0) {
             var grUpdateState = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
             grUpdateState.addQuery('sys_id', 'IN', removedTaskIds.join(','));
             grUpdateState.query();
             while (grUpdateState.next()) {
                 grUpdateState.setValue('state', '1');
                 grUpdateState.update();
             }
         }*/
        // gs.info('tasks exists' + bulkID);
        // //close the bulk where no tasks exists
        if (bulkID) {
            var ctask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            //gs.info('tasks exists illumina0' + bulkID);
            ctask.addEncodedQuery('active=true^bulk_id=' + bulkID);
            ctask.query();
            if (!ctask.next()) {
                //gs.info(bulkID + 'No tasks exists illumina1');
                var bulk = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
                bulk.addQuery("sys_id", bulkID);
                bulk.query();
                if (bulk.next()) {
                    bulk.setValue('state', '7'); //state=cancelled
                    //gs.info(bulk.number + 'illumina2');
                    bulk.update();
                }
            }
            //else {
            //     gs.info('Not found');
            // }
        }
