    //3545 Cancel Button on Bulk form-Maker  "Distance"
    CancelMakerTask: function(sysparm_bulkSysID) {

        //var bulkSysID = this.getParameter('sysparm_bulkSysID'); //get the passed bulk sys_id
        var bulkType;

        var grBulk = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
        if (grBulk.get(bulkSysID)) {
            bulkType = grBulk.bulk_type;

            var cusTsk = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            cusTsk.addEncodedQuery('active=true^trade_task_type=Maker^bulk_id=' + bulkSysID);
            cusTsk.query();
            while (cusTsk.next()) {
                cusTsk.bulk_id = "NULL"; // Fix for defect MSSCUSTODY-3778, set the "Bulk id" for case and task to blank after cancel the Bulk

                if (bulkType == 'manual_task') { //If Manual task, cancel it and close all the associated Cases
                    cusTsk.setValue('state', '7');
                    cusTsk.setValue('active', 'false');
                    //3993.
                    cusTsk.lock = false;
                    cusTsk.setValue('assigned_to', '');
                    cusTsk.setValue('assignment_group', '');

                    var cusCase = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                    if (cusCase.get(cusTsk.trade_case_id)) {
                        var grFlow = new GlideRecord('sys_flow_context'); // Cancelling the flow context when the case is closing
                        grFlow.addQuery('source_record', cusTsk.trade_case_id);
                        grFlow.query();
                        while (grFlow.next()) {
                            sn_fd.FlowAPI.cancel(grFlow.sys_id, 'Cancelling active flows when cancel the bulk');
                        }

                        cusCase.bulk_id = "NULL"; // Fix for defect MSSCUSTODY-3778, set the "Bulk id" for case and task to blank after cancel the Bulk
                        cusCase.setValue('state', '3');
                        cusCase.setValue('active', 'false');
                        cusCase.update();
                    }

                } else if (bulkType == 'automated_task') { //If Automated task, Nullify bulk id form Task, Task Outcome field to be set as null, Task State to be set as New, Task assignment group/assigned to be null

                    //MSSCUSTODY-3993, MSSCUSTODY-4295
                    cusTsk.lock = false;
                    cusTsk.setValue('state', '1');
                    cusTsk.setValue('assigned_to', '');
                    cusTsk.setValue('assignment_group', '');

                    // Fix for defect MSSCUSTODY-3778, set the "Bulk id" for case and task to blank after cancel the Bulk
                    var cusCase1 = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
                    if (cusCase1.get(cusTsk.trade_case_id)) {
                        cusCase1.bulk_id = "NULL";
                        cusCase1.update();
                    }
                }
                cusTsk.update();
            }

            //Cancel the bulk
            grBulk.lock = false;
            grBulk.assigned_to = '';
            grBulk.state = 7;
            grBulk.update();
        }
    },
    cancelvisibility: function(bulkID) {
        var grTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
        grTask.addEncodedQuery('active=true^trade_task_type=Maker^sub_trade_task_type=Maker^bulk_id=' + bulkID);
