        }
        return taskvisbility;
    },

    DisplayLoader: function(sysparm_bulkid) {
        //var bulkId = this.getParameter('sysparm_bulkid');
        var cases = 0;
        var tasks = 0;
        var gaCs = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_case');
        gaCs.addQuery('bulk_id', bulkId);
        gaCs.addAggregate('COUNT');
        gaCs.query();
        if (gaCs.next()) {
            cases = gaCs.getAggregate('COUNT');
        }

        var gaTsk = new GlideAggregate('x_hsb11_mss_c_proc_mss_custody_task');
        gaTsk.addQuery('bulk_id', bulkId);
        gaTsk.addAggregate('COUNT');
        gaTsk.query();
        if (gaTsk.next()) {
            tasks = gaTsk.getAggregate('COUNT');
            if (cases == tasks) {
                return true;
            } else
                return false;
        }
    },

    //MSSCUSTODY-3733 / 3732 / 3731
    updateAutomatedManulTask: function(objectid, trade_case_id) {
        //Query any active case under the trade ID, exclude the new case id, and the case under bluk
        var grCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
        grCase.addQuery('trade_id', objectid);
        grCase.addQuery('sys_id', '!=', trade_case_id);
        grCase.addNotNullQuery('bulk_id');
        grCase.query();

        var bulk_id = '';
        var trade_case_type = '';
        var u_case_sys_id = '';

        //gs.info("MSSCUSTODY-3733, count:" + grCase.getRowCount() + ".trade_case_id:" + trade_case_id);
        while (grCase.next()) {
            bulk_id = grCase.getValue('bulk_id');
            trade_case_type = grCase.trade_id.case_type;
            //gs.info("MSSCUSTODY-3733, count:" + grCase.getRowCount() + ".trade_case_id:" + grCase.sys_id + ".trade_case_type:" + trade_case_type + ".case status:" + grCase.state + ".bulk_id:" + bulk_id);
            //Get task
            var grTasks = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            grTasks.addQuery('trade_case_id', grCase.sys_id);
            grTasks.query();

            if (grTasks.next()) {
                if (trade_case_type == "automated") {
                    debug_msg = 'Delink automated';

                    //MSSCUSTODY-3733
                    //Delink case
                    grCase.setValue('bulk_id', 'NULL');
                    u_case_sys_id = grCase.update();

                    //Delink Task
                    grTasks.setValue('bulk_id', 'NULL');
                    //3933
                    grTasks.lock = false;
                    var u_au_task_sys_id = grTasks.update();

                } else if (trade_case_type == "manual" && grTasks.state != 7) {
                    //MSSCUSTODY-3732
                    debug_msg = 'canncelled manual';

                    //Close the flow
                    var grFlow = new GlideRecord('sys_flow_context'); // Cancelling the flow context when the case is closing as part of FOL Event
                    grFlow.addQuery('source_record', grCase.sys_id);
                    grFlow.query();
                    while (grFlow.next()) {
                        sn_fd.FlowAPI.cancel(grFlow.sys_id, 'Cancelling active flows for active false custody cases');
                        //gs.info("this cancels the flow");
                    }

                    grTasks.sub_trade_task_type = "GHSS Interim Update"; //MSSCUSTODY-4307

                    // cancel the case then close the flow
                    grCase.setValue('state', 7);
                    grCase.setValue('active', 'false');
                    grCase.work_notes = 'Case cancelled due to creation of automated case for same trade.';
                    u_case_sys_id = grCase.update();

                    // Cancel the task
                    grTasks.setValue('state', 7);
                    grTasks.setValue('active', 'false');
                    grTasks.work_notes = 'Task cancelled due to creation of automated task for same trade.';
                    //3933
                    grTasks.lock = false;

                    //update task
                    var u_ma_task_sys_id = grTasks.update();
                }
                //MSSCustody 4282
                new x_hsb11_mss_c_proc.MSSCustodyBulkUtils_workspace().decrementTradeCount(bulk_id);
            }
            this.cancelBulk(bulk_id);
        }
    },

    cancelBulk: function(bulk_id) {
        //no_open_case not handle.
        if (!gs.nil(bulk_id)) {
            // check any active task under this automated / manual bulk, if no then cancel the bulk
            var grBulkAutomatedTasks = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task");
            grBulkAutomatedTasks.addQuery('bulk_id', bulk_id);
            grBulkAutomatedTasks.addQuery('active', 'true');
            grBulkAutomatedTasks.query();
            //gs.info("MSSCUSTODY-3733: grBulkAutomatedTasks :" + grBulkAutomatedTasks.getRowCount());
            if (!grBulkAutomatedTasks.next()) {
                var grBulkTransaction = new GlideRecord("x_hsb11_hsbc_mss_o_hsbc_bulk_transaction");
                if (grBulkTransaction.get(bulk_id)) {
                    // if already cancel no action
                    if (grBulkTransaction.state != 3) {
                        grBulkTransaction.setValue('state', 3);
                        var bc_sys_id = grBulkTransaction.update();

                    }

                }

            }
        }
    },

