    gettaskdetails: function(bulkid, market) {

        var taskIdArray = []; //Define Array variable
        var taskCount = 0; //Define number variable
        var checkTaskCount = 0;

        var taskDetails = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_task"); //Fetch data from task table
        taskDetails.addEncodedQuery('active=true^bulk_id!=null^trade_id.owning_business=' + market + '^bulk_id=' + bulkid);
        taskDetails.query(); //Execute the query
        while (taskDetails.next()) {
            if (taskDetails.trade_task_type == 'Maker' && (taskDetails.state == '1' || taskDetails.state == '2')) {
                taskIdArray.push(taskDetails.number.toString()); //Add Task Ids to array
                taskCount++;
            } else if (taskDetails.trade_task_type == 'Checker' && (taskDetails.state == '1' || taskDetails.state == '2')) {
                taskIdArray.push(taskDetails.number.toString()); //Add Task Ids to array
                checkTaskCount++;
            }
        }
        tradelifecycle = taskDetails.trade_id.trade_lifecycle_status;

        g_scratchpad.taskCount = taskCount; //Update scratchpad
        g_scratchpad.taskIdArray = taskIdArray; //Update scratchpad
        g_scratchpad.checkTaskCount = checkTaskCount; //Update Scratchpad
        g_scratchpad.tradelifecycle = tradelifecycle; //Update Scratchpad
    },


