    bulkUnavailableUserInformation: function(sysparm_query) { //MSSCUSTODY-5172

        /*
        This property is utlized to determine which all market is allowed to do a bulk operation.
        1) Addition of the market in the value would allow the bulk operation
        2) Removal would disable the bulk functionality

        Artifacts involved:
        1) System property: x_hsb11_mss_c_proc.enableautomatedbulk.market
        2) Script Include: x_hsb11_mss_c_proc.MSSCustodyBulkUtils_workspace  - Method: bulkUnavailableUserInformation
        3) UI Context Menu: Create Bulk for Selected
        4) UI Context menu: Create Bulk for All Filtered
        */
        try {
            //var query = this.getParameter('sysparm_query');
            var enableBulkOption = false;
            var arrMarket = [];
            var outcomesArray = [];
            var arrConfirmTrade = [];
            var arrPutTradeOnHold = [];
            var arrResumeTrade = [];
            var arrSettleTrade = [];
            var arrProcessTradeCancel = [];
            var arrTradeAmend = [];
            var market = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedbulk.market');
            var count = 0;

            // fetching associated markets
            var user1 = new GlideRecord('sys_user');
            user1.get(gs.getUserID());
            usermarket = user1.u_associated_business_markets;


            var grTradeDBView = new GlideAggregate('x_hsb11_mss_c_proc_custody_trades');
            grTradeDBView.addEncodedQuery(query);
            grTradeDBView.groupBy('custodytrade_owning_business');
            grTradeDBView.groupBy('custodytrade_trade_lifecycle_status');
            grTradeDBView.query();
            while (grTradeDBView.next()) {
                var flag = false;
                var grTradeOwningBsuiness = grTradeDBView.custodytrade_owning_business.toString();
                var grTrdLifeCycleStatus = grTradeDBView.custodytrade_trade_lifecycle_status.toString();

                //Return false if selected trade record does not find matching market.
                if (market.indexOf(grTradeOwningBsuiness) == -1) {
                    enableBulkOption = 'Creating Bulk is not allowed because it is not yet enabled for the market to which the selected trades belong.';
                    break;
                }

                //Return false if selected trade records are from different markets.
                if (arrMarket.indexOf(grTradeOwningBsuiness.toString()) == -1) {
                    arrMarket.push(grTradeOwningBsuiness.toString());
                    if (arrMarket.length > 1) {
                        enableBulkOption = 'Creating Bulk is not allowed due to different owning business for the selected trades. Kindly select trades with same owning business and try again.';
                        break;
                    }
                }

                //Return false if selected trade records does not find matching market in user profile.
                if (usermarket.indexOf(grTradeOwningBsuiness.toString()) == -1) {
                    enableBulkOption = 'Creating Bulk is not allowed because user does not have access to the owning business of the selected trades.';
                    break;
                }

                //Check BPS table for outcome option 
                var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + grTradeOwningBsuiness + '^ctac_code=' + grTrdLifeCycleStatus);
                //grBulkEvents.orderBy(grTrdLifeCycleStatus);
                grBulkEvents.query();
                if (grBulkEvents.next()) {
                    flag = true;
                    if (count == 0) {
                        arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        arrResumeTrade = grBulkEvents.resume_trade.toString();
                        arrSettleTrade = grBulkEvents.settle_trade.toString();
                        arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        arrTradeAmend = grBulkEvents.trade_amend.toString();
                    } else {
                        if (grBulkEvents.confirm_trade.toString().indexOf("false") > -1) {
                            arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        }
                        if (grBulkEvents.put_trade_on_hold.toString().indexOf("false") > -1) {
                            arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        }
                        if (grBulkEvents.resume_trade.toString().indexOf("false") > -1) {
                            arrResumeTrade = grBulkEvents.resume_trade.toString();
                        }
                        if (grBulkEvents.settle_trade.toString().indexOf("false") > -1) {
                            arrSettleTrade = grBulkEvents.settle_trade.toString();
                        }
                        if (grBulkEvents.process_trade_cancellation.toString().indexOf("false") > -1) {
                            arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        }
                        if (grBulkEvents.trade_amend.toString().indexOf("false") > -1) {
                            arrTradeAmend = grBulkEvents.trade_amend.toString();
                        }
                    }
                    count = ++count;
                }

            }
            if (flag == true) {
                outcomesArray.push(arrConfirmTrade, arrPutTradeOnHold, arrResumeTrade, arrSettleTrade, arrProcessTradeCancel, arrTradeAmend); //pushed all the outcome values in temp array
                if (outcomesArray.indexOf('true') > -1) {
                    gs.info("In here");
                    enableBulkOption = true;
                } else {
                    enableBulkOption = 'Creating Bulk is not allowed for the combination of the lifecycle status for the selected trades. Kindly review the selected trades and try again.';
                }
            }

            return enableBulkOption;

        } catch (e) {
            gs.error("Unexpected error occured during bulk info message from bulkUnavailableUserInformation: " + e.message); //MSSOTIQUBE-1096
        }


    },

    evalAmendOptionTradeList: function(sysparm_query, sysparm_amendOptionField) { //MSSCUSTODY-5331
        //var query = this.getParameter('sysparm_query');
        //var bulkOptionField = this.getParameter('sysparm_amendOptionField');
        var enableAmendOption = false;
        var arrMarket = [];
        var market = gs.getProperty('x_hsb11_mss_c_proc.enableautomatedamend.market');

        // fetching associated markets
        var user1 = new GlideRecord('sys_user');
        user1.get(gs.getUserID());
        usermarket = user1.u_associated_business_markets;

        var grTradeDBView = new GlideAggregate('x_hsb11_mss_c_proc_custody_trades');
        grTradeDBView.addEncodedQuery(query);
        grTradeDBView.groupBy('custodytrade_owning_business');
        grTradeDBView.groupBy('custodytrade_trade_lifecycle_status');
        grTradeDBView.query();

        while (grTradeDBView.next()) {

            //Return false if selected task record does not find matching market.
            if (market.indexOf(grTradeDBView.custodytrade_owning_business) == -1) {
                enableAmendOption = false;
                break;
            }


            //Return false if selected trade records are from different markets.
            if (arrMarket.indexOf(grTradeDBView.custodytrade_owning_business.toString()) == -1) {
                arrMarket.push(grTradeDBView.custodytrade_owning_business.toString());
                if (arrMarket.length > 1) {
                    enableAmendOption = false;
                    break;
                }
            }

            //Check BPS table for outcome option 
            var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage');
            grBulkEvents.addEncodedQuery('active=true^business_process.process_name=Trade Lifecycle Status^market=' + grTradeDBView.custodytrade_owning_business + '^ctac_code=' + grTradeDBView.custodytrade_trade_lifecycle_status + '^' + bulkOptionField + '=true');
            grBulkEvents.orderBy(bulkOptionField);
            grBulkEvents.query();
            if (grBulkEvents.next()) {
                enableAmendOption = true;
            } else {
                enableAmendOption = false;
                break;
            }

            if (usermarket.indexOf(grTradeDBView.custodytrade_owning_business.toString()) == -1) {
                enableAmendOption = false;
                break;
            }

        }
        return enableAmendOption;

    },

