            //     gs.info('5331 Amend flag ' + grBulkEvents1.trade_amend);
            //     if ((trdCount <= 51) && (amendFlag)) {
            //         flag = 'true';
            //     } else {
            //         flag = 'parent menu false';
            //     }
            //     gs.info('5331' + flag)
            //     return flag;
            // }
            for (var i = 0; i < trdlifeStatus.length; i++) {
                var grBulkEvents = new GlideRecord('x_hsb11_hsbc_mss_o_business_process_stage'); //check for the matching record in BPS table
                grBulkEvents.addEncodedQuery('business_process.process_name=Trade Lifecycle Status^market=' + trdmarket[i] + '^ctac_code=' + trdlifeStatus[i]);
                //grBulkEvents.orderBy(grTrdLifeCycleStatus);
                grBulkEvents.query();
                if (grBulkEvents.next()) {
                    //flag = true;
                    if (count == 0) {
                        arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        arrResumeTrade = grBulkEvents.resume_trade.toString();
                        arrSettleTrade = grBulkEvents.settle_trade.toString();
                        arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        arrTradeAmend = grBulkEvents.trade_amend.toString();
                    } else {
                        if (grBulkEvents.confirm_trade.toString().indexOf("false") > -1) {
                            arrConfirmTrade = grBulkEvents.confirm_trade.toString();
                        }
                        if (grBulkEvents.put_trade_on_hold.toString().indexOf("false") > -1) {
                            arrPutTradeOnHold = grBulkEvents.put_trade_on_hold.toString();
                        }
                        if (grBulkEvents.resume_trade.toString().indexOf("false") > -1) {
                            arrResumeTrade = grBulkEvents.resume_trade.toString();
                        }
                        if (grBulkEvents.settle_trade.toString().indexOf("false") > -1) {
                            arrSettleTrade = grBulkEvents.settle_trade.toString();
                        }
                        if (grBulkEvents.process_trade_cancellation.toString().indexOf("false") > -1) {
                            arrProcessTradeCancel = grBulkEvents.process_trade_cancellation.toString();
                        }
                        if (grBulkEvents.trade_amend.toString().indexOf("false") > -1) {
                            arrTradeAmend = grBulkEvents.trade_amend.toString();
                        }
                    }
                    count = ++count;
                }
                outcomearr.push(arrConfirmTrade, arrPutTradeOnHold, arrResumeTrade, arrSettleTrade, arrProcessTradeCancel, arrTradeAmend);
                if (outcomearr.indexOf('true') > -1) {
                    outcomeChk = true;
                }
            }
            if (((trdCount == 51) && (outcomearr[5].toString() == 'true')) || ((trdCount > 51) && (outcomeChk))) {
                flag = 'true';
            } else {
                flag = "Creating Bulk is not allowed as only one trade is selected, kindly filter more trades. Amend is not applicable for the selected Lifecycle Status.";
            }
            return flag;
        } catch (e) {
            gs.error("Unexpected error occured during Amend info message: enableSelectedParentMenu" + e.message); //MSSOTIQUBE-1096
        }
    },
};
